export const STRIDE=6;const R=0,p=1,h=2,x=3,g=540;let o=[],t=null,c=0,d=0;export function startRecording(i){return o=i.map(n=>n.settings.position),o.includes("ball")||o.push("ball"),t=new Float32Array(o.length*6*540),c=0,d=0,o.slice()}function f(){if((c+1)*o.length*6<=t.length)return;const n=new Float32Array(t.length*2);n.set(t),t=n}export function record(i){if(!t)return;f();const n=c*o.length*6;t.fill(0,n,n+o.length*6);for(const e of i){const l=o.indexOf(e.settings.position);if(l===-1)continue;const s=n+l*6;t[s]=e.coords.x,t[s+1]=e.coords.y,t[s+2]=e.coords.z||0,t[s+3]=e.state&&e.state.xSpeed||0,t[s+4]=e.state&&e.state.ySpeed||0,t[s+5]=e.settings.benched?0:e.state&&e.state.hasBall?e.state.run?3:2:1}c+=1}export function frameCount(){return c}export function slotNames(){return o.slice()}export function frameAt(i,n){if(!t||c===0)return[];const l=Math.max(0,Math.min(c-1,Math.floor(i)))*o.length*6,s=[];for(let r=0;r<o.length;r+=1){const a=l+r*6,u=o[r];s.push({settings:{position:u,team:n?n(u):0,benched:t[a+5]===0},coords:{x:t[a],y:t[a+1],z:t[a+2]},state:{xSpeed:t[a+3],ySpeed:t[a+4],hasBall:t[a+5]===2||t[a+5]===3,run:t[a+5]===3}})}return s}export function focusAt(i){const n=frameAt(i),e=n.find(r=>r.state.hasBall&&!r.settings.benched);if(e)return{...e.coords,holder:e.settings.position};const l=n.find(r=>r.settings.position==="ball"&&!r.settings.benched);if(l&&(l.coords.x||l.coords.y))return{...l.coords,holder:""};const s=n.find(r=>r.settings.position==="qb");return s?{...s.coords,holder:""}:{x:0,y:0,z:0,holder:""}}export function rewind(){d=0}export function advance(i,n,e=1){return d+=i*n*e,d>=c}export function playheadFrame(){return d}export function isEmpty(){return c===0}export function discard(){t=null,o=[],c=0,d=0}
